        pygame.draw.circle(self.screen, (255,255,255), (cx-sz//4, cy-sz//4), max(int(sz//3), 1))
        self.snake.draw(self.screen)
        self.particles.draw(self.screen)
        if self.game_state == GameState.START: self.draw_start_screen()
        elif self.game_state == GameState.GAME_OVER: self.draw_game_over()
    def run(self):
        keys = pygame.key.KeyType()
        running = True
        while running:
            for e in pygame.event.get():
                if e.type == pygame.QUIT: running = False
                elif e.type == pygame.KEYDOWN: keys[e.key]
            self.handle_input(keys)
            self.update()
            self.draw()
            pygame.display.flip()
            self.clock.tick(FPS)
        pygame.quit(); sys.exit()

if __name__ == '__main__':
    Game().run()
